/**
 * The inbound-email Worker (#1217).
 *
 * Cloudflare Email Routing hands every message sent to a store address (orders@, support@ …) to
 * this Worker's `email()` handler. It asks the application which vendor owns the address and where
 * the store's real mailbox is, then forwards the message there.
 *
 * WHY A SEPARATE WORKER. `.open-next/worker.js` is generated by `opennextjs-cloudflare build` and
 * exports only `fetch`, so there is nowhere on the application Worker to attach an `email` handler —
 * the same reason `workers/scheduler` exists. Like the scheduler it holds no database and no vendor
 * knowledge: it calls `/api/inbound-email/resolve` with a shared secret.
 *
 * NOTHING IS LOST. On any failure other than a definite "unknown address" (404) — a network error,
 * a 5xx, a misconfigured token — the message goes to INBOUND_FALLBACK_FORWARD instead, so an
 * application outage never drops a customer's email.
 *
 * NOTHING PERSONAL IS LOGGED. The one log line carries the vendor id, purpose, order flag and order
 * number — never the sender, the subject or the body (R22). After it, an order-related message asks
 * `/api/inbound-email/alert` to alert the store's staff (`#1390`).
 */

export interface Env {
  /** Origin of the application Worker, e.g. `https://aheed-staging.merqify.com`. */
  APP_BASE_URL: string;
  /** Shared secret proving to the application that a request came from here. */
  INBOUND_EMAIL_TOKEN: string;
  /** A verified Email Routing destination that receives mail whenever resolving fails. */
  INBOUND_FALLBACK_FORWARD: string;
}

/** The part of Cloudflare's ForwardableEmailMessage this Worker uses, so tests can fake it. */
export interface InboundMessage {
  readonly to: string;
  readonly from?: string;
  readonly raw?: ReadableStream<Uint8Array>;
  readonly headers: Headers;
  forward(rcptTo: string, headers?: Headers): Promise<unknown>;
  setReject(reason: string): void;
}

interface Resolution {
  forwardTo: string;
  vendorId: string;
  purpose: string;
  orderRelated: boolean;
  orderNumber: string | null;
}

export const RESOLVE_PATH = "/api/inbound-email/resolve";
export const ALERT_PATH = "/api/inbound-email/alert";
export const RECORD_PATH = "/api/inbound-email/record";

async function forwardToFallback(message: InboundMessage, env: Env, why: string): Promise<void> {
  console.error(`inbound-email resolve failed (${why}); forwarding to the fallback mailbox`);
  await message.forward(env.INBOUND_FALLBACK_FORWARD);
}

export async function handleInboundEmail(message: InboundMessage, env: Env): Promise<void> {
  let response: Response;
  try {
    response = await fetch(new URL(RESOLVE_PATH, env.APP_BASE_URL), {
      method: "POST",
      headers: { "content-type": "application/json", "x-inbound-token": env.INBOUND_EMAIL_TOKEN },
      body: JSON.stringify({ to: message.to, subject: message.headers.get("subject") ?? "" }),
    });
  } catch {
    await forwardToFallback(message, env, "network error");
    return;
  }

  if (response.status === 404) {
    message.setReject("Unknown recipient");
    console.log("inbound-email rejected: no store owns this address");
    return;
  }

  if (!response.ok) {
    await forwardToFallback(message, env, `status ${response.status}`);
    return;
  }

  let resolution: Resolution;
  try {
    resolution = (await response.json()) as Resolution;
  } catch {
    await forwardToFallback(message, env, "unreadable response");
    return;
  }

  await message.forward(resolution.forwardTo);
  console.log(
    `inbound-email vendorId=${resolution.vendorId} purpose=${resolution.purpose} ` +
      `orderRelated=${resolution.orderRelated} orderNumber=${resolution.orderNumber ?? "none"}`,
  );

  if (message.raw) {
    await recordInboundEnquiry(message, env);
  }

  if (resolution.orderRelated) await requestOrderAlert(message, env);
}

function parseFromEmailAddress(header: string | null, envelopeFrom?: string): string {
  if (header) {
    const match = /<([^>]+@[^>]+)>/.exec(header);
    if (match) return match[1].trim();
    if (header.includes("@") && !header.includes(" ")) return header.trim();
  }
  return envelopeFrom?.trim() || "unknown@sender";
}

function extractBodyFromRawEmail(rawText: string): string {
  const splitIdx = rawText.search(/\r?\n\r?\n/);
  if (splitIdx === -1) return "";
  const bodyPart = rawText.slice(splitIdx).replace(/^\r?\n\r?\n/, "");
  const plainMatch =
    /Content-Type:\s*text\/plain[^\r\n]*(?:\r?\n[^\r\n]+)*\r?\n\r?\n([\s\S]*?)(?:\r?\n--|\s*$)/i.exec(
      rawText,
    );
  const candidate = plainMatch ? plainMatch[1] : bodyPart;
  return candidate
    .replace(/=\r?\n/g, "")
    .replace(/=([0-9A-Fa-f]{2})/g, (_m, hex: string) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/<[^>]+>/g, " ")
    .trim()
    .slice(0, 4000);
}

async function recordInboundEnquiry(message: InboundMessage, env: Env): Promise<void> {
  try {
    let rawText = "";
    if (message.raw) {
      rawText = await new Response(message.raw).text();
    }
    const fromHeader = message.headers.get("from");
    const fromEmail = parseFromEmailAddress(fromHeader, message.from);
    const fromName = parseFromDisplayName(fromHeader);
    const bodyText = extractBodyFromRawEmail(rawText) || "(No message body)";
    await fetch(new URL(RECORD_PATH, env.APP_BASE_URL), {
      method: "POST",
      headers: { "content-type": "application/json", "x-inbound-token": env.INBOUND_EMAIL_TOKEN },
      body: JSON.stringify({
        to: message.to,
        fromEmail,
        fromName,
        subject: message.headers.get("subject") ?? "(No subject)",
        message: bodyText,
      }),
    });
  } catch {
    console.error("inbound-email record call failed");
  }
}

/**
 * #1390 R9 — ask the application to alert the store's staff. Only AFTER `forward()` has resolved,
 * so an alert can never delay or break delivery; a failure here is logged and swallowed. The body
 * carries the sender's display name only, never their address. The application re-resolves the
 * address itself rather than trusting a vendor id from this side.
 */
async function requestOrderAlert(message: InboundMessage, env: Env): Promise<void> {
  try {
    const response = await fetch(new URL(ALERT_PATH, env.APP_BASE_URL), {
      method: "POST",
      headers: { "content-type": "application/json", "x-inbound-token": env.INBOUND_EMAIL_TOKEN },
      body: JSON.stringify({
        to: message.to,
        subject: message.headers.get("subject") ?? "",
        fromName: parseFromDisplayName(message.headers.get("from")),
      }),
    });
    if (!response.ok) console.error(`inbound-email alert call failed (${response.status})`);
  } catch {
    console.error("inbound-email alert call failed (network error)");
  }
}

/** A UTF-8 RFC 2047 encoded word (`=?UTF-8?B?…?=` or `?Q?`), decoded; anything else unchanged. */
function decodeEncodedWords(value: string): string {
  return value.replace(
    /=\?([^?]+)\?([bBqQ])\?([^?]*)\?=/g,
    (whole, charset: string, encoding: string, text: string) => {
      if (charset.toLowerCase() !== "utf-8") return whole;
      try {
        let bytes: Uint8Array;
        if (encoding.toLowerCase() === "b") {
          bytes = Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
        } else {
          const ascii = text
            .replace(/_/g, " ")
            .replace(/=([0-9A-Fa-f]{2})/g, (_m, hex: string) =>
              String.fromCharCode(parseInt(hex, 16)),
            );
          bytes = Uint8Array.from(ascii, (c) => c.charCodeAt(0));
        }
        return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
      } catch {
        return whole;
      }
    },
  );
}

/**
 * #1390 R10 — the display name from a `From` header (`"Jane Doe" <j@x.com>` gives `Jane Doe`), or
 * null when there is none. The address part is never returned, and neither is a "name" containing
 * `@`: some clients send `"j@x.com" <j@x.com>` when no name is set, which would leak the address.
 */
export function parseFromDisplayName(header: string | null): string | null {
  if (!header) return null;
  const angle = header.lastIndexOf("<");
  if (angle <= 0) return null;
  let name = header.slice(0, angle).trim();
  if (name.startsWith('"') && name.endsWith('"') && name.length >= 2) {
    name = name.slice(1, -1).replace(/\\(.)/g, "$1").trim();
  }
  if (name === "") return null;
  const decoded = decodeEncodedWords(name);
  return decoded.includes("@") ? null : decoded;
}

const inboundEmailWorker = {
  async email(message: InboundMessage, env: Env, _ctx: ExecutionContext): Promise<void> {
    await handleInboundEmail(message, env);
  },
};

export default inboundEmailWorker;
